solution_plantuml:
@startuml
class Zahlung {
  - betrag : Decimal
  + ausfuehren() : Boolean
}
class Kreditkartenzahlung {
  - kartenende : String
}
class Ueberweisung {
  - iban : String
}
class Bestellung {
  - nummer : String
}
class Bestellposition {
  - menge : Integer
}
Zahlung <|-- Kreditkartenzahlung
Zahlung <|-- Ueberweisung
Bestellung *-- Bestellposition
Bestellung -> Zahlung : bezahlt mit
@enduml

@startuml
class Benutzer {
  - id : Integer
  - name : String
}
class Kunde {
  - kundennummer : String
}
class SupportMitarbeiter {
  - kuerzel : String
}
class Ticket {
  - betreff : String
  - status : String
}
class Kommentar {
  - text : String
  - erstelltAm : DateTime
}
Benutzer <|-- Kunde
Benutzer <|-- SupportMitarbeiter
Kunde -> Ticket : meldet
Ticket -> SupportMitarbeiter : zugewiesen an
Ticket *-- Kommentar
@enduml

@startuml
class Person {
  - name : String
  - email : String
}
class Teilnehmer {
  - teilnehmernummer : String
}
class Dozent {
  - kuerzel : String
}
class Kurs {
  - titel : String
}
class Anmeldung {
  - anmeldedatum : Date
  - status : String
}
Person <|-- Teilnehmer
Person <|-- Dozent
Dozent -> Kurs : leitet
Teilnehmer -> Anmeldung
Anmeldung -> Kurs
@enduml

@startuml
start
:Ticket empfangen;
:Ticket priorisieren;
if (Direkt loesbar?) then (ja)
  :Loesung umsetzen;
  :Loesung dokumentieren;
else (nein)
  :Ticket eskalieren;
endif
stop
@enduml
